 * @param reference - A `file://` reference string.
 * @returns The parsed filename and optional functionName.
 */
export function parseFileTransformReference(reference: string): {
  filename: string;
  functionName?: string;
} {
  const withoutProtocol = reference.startsWith('file://')
    ? reference.slice('file://'.length)
    : reference;

  const lastColonIndex = withoutProtocol.lastIndexOf(':');
  if (lastColonIndex !== -1) {
    const maybeFilename = withoutProtocol.slice(0, lastColonIndex);
    const maybeFunctionName = withoutProtocol.slice(lastColonIndex + 1);
    if (isJavascriptFile(maybeFilename)) {
      return { filename: maybeFilename, functionName: maybeFunctionName };
    }
  }

  return { filename: withoutProtocol };
}

